<template>
  <div class="widget-trustindex">
    <a href="https://m-strana.ru/" target="_blank" class="widget-trustindex-logo">
      <img alt="mstrana logo" src="./assets/logo.png" class="widget-trustindex-image">

      <p class="widget-trustindex-logo__text">
        Выставка домов <br>малоэтажная страна
      </p>
    </a>

    <div v-if="company" class="widget-trustindex-wrap">
        <div class="widget-trustindex-content">
          <a v-if="slug" :href="`https://m-strana.ru/trustindex/company/${ slug }/`" class="widget-trustindex-name">
            {{ company.name }}
          </a>

          <p class="widget-trustindex-text">
            TiMs - Trust Index MS (Индекс надежности МС)
          </p>
        </div>

        <div class="widget-trustindex-tims" :style="{ color: colorScore }">
            <IconCircleHalf />
            <div class="widget-trustindex-tims__score">
                <p>
                    {{ prepareScore( company.final_score ) }}
                </p>
                <IconTims class="widget-trustindex-tims__score__icon" />
            </div>
        </div>
    </div>

    <div class="widget-trustindex-score">
      <div>
        <CircleScore
            :value="osiScore"
            size="64"
            :color-filled="getStyleScore( osiScore )"
            :color-unfilled="getStyleScore( osiScore )"
            :box-shadow="getShadowForScore( osiScore )"
        >
            <IconOsi class="widget-trustindex-score__icon" />
            <span class="widget-trustindex-score__value" :style="{ color: getStyleScore( osiScore ) }">{{ osiScore }}</span>
        </CircleScore>

        <p class="widget-trustindex-score__title">
          Баллы OSI
        </p>
      </div>

      <div>
        <CircleScore
            :value="rmsScore"
            size="64"
            :color-filled="getStyleScore( rmsScore )"
            :color-unfilled="getStyleScore( rmsScore )"
            :box-shadow="getShadowForScore( rmsScore )"
        >
            <IconRms class="widget-trustindex-score__icon" />
            <span class="widget-trustindex-score__value" :style="{ color: getStyleScore( rmsScore ) }">{{ rmsScore }}</span>
        </CircleScore>

        <p class="widget-trustindex-score__title">
          Рейтинг RMS
        </p>
      </div>

      <div>
        <CircleScore
            :value="coScore"
            size="64"
            :color-filled="getStyleScore( coScore )"
            :color-unfilled="getStyleScore( coScore )"
            :box-shadow="getShadowForScore( coScore )"
        >
            <IconCo class="widget-trustindex-score__icon" />
            <span class="widget-trustindex-score__value" :style="{ color: getStyleScore( coScore ) }">{{ coScore }}</span>
        </CircleScore>

        <p class="widget-trustindex-score__title">
          Баллы CO
        </p>
      </div>

      <div>
        <CircleScore
            :value="srScore"
            size="64"
            :color-filled="getStyleScore( srScore )"
            :color-unfilled="getStyleScore( srScore )"
            :box-shadow="getShadowForScore( srScore )"
        >
            <IconSr class="widget-trustindex-score__icon" />
            <span class="widget-trustindex-score__value" :style="{ color: getStyleScore( srScore ) }">{{ srScore }}</span>
        </CircleScore>

        <p class="widget-trustindex-score__title">
          Рейтинг SR
        </p>
      </div>
    </div>
  </div>
</template>

<script>
import IconCircleHalf from './components/Icon/CircleHalf.vue'
import IconTims from './components/Icon/Tims.vue'
import CircleScore from './components/CircleScore.vue'
import IconOsi from './components/Icon/Osi.vue'
import IconRms from './components/Icon/Rms.vue'
import IconCo from './components/Icon/Co.vue'
import IconSr from './components/Icon/Sr.vue'

export default {
  name: 'App',
  components: {
    IconCircleHalf,
    IconTims,
    CircleScore,
    IconOsi,
    IconRms,
    IconCo,
    IconSr
  },
  data() {
      return {
          // reviews: [],
          id: null,
          company: null,
          slug: null,
          colorScore: '#EA412C',
          loading: true,
      }
  },
  computed:
  {
    osiScore()
    {
      return this.company ? this.prepareScore( this.company.osi_score ) || 0 : 0
    },
    rmsScore()
    {
      return this.company ? this.prepareScore( this.company.rms_score ) || 0 : 0
    },
    coScore()
    {
      return this.company ? this.prepareScore( this.company.co_score ) || 0 : 0
    },
    srScore()
    {
      return this.company ? this.prepareScore( this.company.sr_score ) || 0 : 0
    },
  },
  methods:
  {
      prepareScore( score )
      {
          const value = typeof score === 'string' ? +score : score
          return Number( ( value / 10 ).toFixed( 1 ) )
      },
      getStyleScore( score )
      {
          if ( score >= 6.5 )
          {
              return '#54B600'
          }

          return score >= 3 ? '#FF7E00' : '#EA412C'
      },
      getShadowForScore( score )
      {
          if ( score >= 6.5 )
          {
              return '0 4px 15px rgba(165, 234, 107, 0.8)'
          }

          return score >= 3 ? '0 4px 15px rgba(255, 192, 119, 1)' : '0 4px 15px rgba(255, 143, 119, 1)'
      },
      async getCompany()
      {
          try {
              // const response = await fetch('http://ваш-сайт/api/reviews');
              // this.reviews = await response.json();

              const response = await fetch('https://m-strana.dtctkmt.ru/api/company/list/', {
                method: 'POST',
                body: JSON.stringify({ ids: [ this.id ] })
              })
              const data = await response.json()

              this.company = data.rows.find( item => item.id === this.id )
              this.colorScore = this.getStyleScore( this.prepareScore( this.company.final_score ) )
          } catch (error) {
              console.error('Ошибка загрузки компаний:', error)
          } finally {
              this.loading = false
          }
      },
      async getSlug()
      {
          if ( this.company.id )
          {
              try {
                  const response = await fetch('https://m-strana.dtctkmt.ru/api/company/slugs/get/by-company/', {
                    method: 'POST',
                    body: JSON.stringify({ company_id: this.company.id })
                  })
                  const data = await response.json()

                  this.slug = data.slug
              } catch (error) {
                  console.error('Ошибка загрузки slug:', error)
              } finally {
                  this.loading = false
              }
          }
      },
      parseUrlParams()
      {
          const params = new URLSearchParams(window.location.search)
          this.id = params.get('company') || null
      }
  },
  async mounted() {
    this.parseUrlParams()

    await this.getCompany()
    await this.getSlug()
  }
}
</script>

