<template>
    <div class="circle-progress">
      <svg
        class="circle-progress__svg"
        viewBox="-2 -2 108 108"
        :width="computedSize"
        :height="computedSize"
      >
        <circle
          class="circle-progress__circle circle-progress__line--back"
          :r="radius"
          cx="52"
          cy="52"
        />
        <circle
          class="circle-progress__circle circle-progress__line--top"
          :class="fillingCircleClasses"
          :style="fillingCircleStyles"
          ref="fillingCircle"
          :r="radiusFilled"
          cx="52"
          cy="52"
          transform="rotate(-90 52 52)"
        />
      </svg>
  
      <div class="circle-progress__wrap" :style="wrapStyles">
        <div class="circle-progress__content">
          <span v-if="percentage" class="circle-progress__percentage">
            {{ getPercentage }}
          </span>
          <slot />
        </div>
      </div>
    </div>
</template>
  
<script>
import { ref, computed } from 'vue'
  
export default {
    name: 'CircleProgress',
    props: {
      max: {
        type: Number,
        default: 10
      },
      value: {
        type: Number,
        required: true
      },
      colorFilled: {
        type: String,
        default: '#FF5533'
      },
      colorUnfilled: {
        type: String,
        default: '#3BB44A'
      },
      boxShadow: {
        type: String,
        default: '0 4px 15px rgba(165, 234, 107, 0.8)'
      },
      colorBack: {
        type: String,
        default: '#ECEEF1'
      },
      percentage: {
        type: Boolean,
        default: false
      },
      rounded: {
        type: Boolean,
        default: false
      },
      animationDuration: {
        type: String,
        default: '0.5s'
      },
      strokeWidth: {
        type: String,
        default: '2px'
      },
      strokeWidthFilled: {
        type: String,
        default: '2px'
      },
      reversedFilling: {
        type: Boolean,
        default: false
      },
      size: {
        type: [String, Number],
        default: '124'
      },
      isInner: {
        type: Boolean,
        default: false
      }
    },
    setup(props) {
      const fillingCircle = ref(null)
      const radius = ref(50)
      const radiusFilled = ref(48)
  
      // Преобразуем size в число, если он строковый
      const computedSize = computed(() => {
        return typeof props.size === 'string' 
          ? parseInt(props.size, 10) 
          : props.size
      })
  
      const isLimitReached = computed(() => props.max <= props.value)
      
      const dashArray = computed(() => radius.value * Math.PI * 2)
      const currentFormatted = computed(() => isLimitReached.value ? props.max : props.value)
      
      const dashOffset = computed(() => {
        if (props.reversedFilling) {
          return dashArray.value - dashArray.value * (props.max - currentFormatted.value) / props.max
        }
        return dashArray.value - dashArray.value * currentFormatted.value / props.max
      })
  
      const fillingCircleClasses = computed(() => ({
        'circle-progress__line--top--rounded': props.rounded,
        'circle-progress__line--filled': isLimitReached.value,
        'circle-progress__line--unfilled': !isLimitReached.value
      }))
  
      const fillingCircleStyles = computed(() => ({
        strokeDashoffset: dashOffset.value,
        strokeDasharray: dashArray.value,
        strokeWidth: props.strokeWidthFilled,
        stroke: isLimitReached.value ? props.colorFilled : props.colorUnfilled,
        animationDuration: props.animationDuration
      }))
  
      const getPercentage = computed(() => {
        return Math.floor(props.value / props.max * 100) + '%'
      })
  
      const wrapStyles = computed(() => {
        const paddingValue = parseInt(props.strokeWidth) + 7
        return {
          padding: `${paddingValue}px`
        }
      })
  
      return {
        fillingCircle,
        radius,
        radiusFilled,
        computedSize,
        isLimitReached,
        dashArray,
        currentFormatted,
        dashOffset,
        fillingCircleClasses,
        fillingCircleStyles,
        getPercentage,
        wrapStyles
      }
    }
  }
</script>
  
<style scoped>
  .circle-progress {
    position: relative;
    display: flex;
    justify-content: center;
    align-items: center;
    max-width: 100%;
    border-radius: 50%;
  }
  
  .circle-progress__svg {
    display: block;
  }
  
  .circle-progress__circle {
    fill: transparent;
  }
  
  .circle-progress__line--back {
    stroke: var(--color-back, #ECEEF1);
    stroke-width: var(--stroke-width, 2px);
    stroke-dashoffset: 0;
  }
  
  .circle-progress__line--top {
    stroke-linecap: round;
    transition: 0.5s all;
    animation-name: filling;
    animation-timing-function: ease-in;
  }
  
  .circle-progress__line--top--rounded {
    stroke-linecap: round;
  }
  
  .circle-progress__line--filled {
    filter: drop-shadow(var(--box-shadow, 0 4px 15px rgba(165, 234, 107, 0.8)));
  }
  
  .circle-progress__wrap {
    position: absolute;
    left: 0;
    right: 0;
    top: 0;
    bottom: 0;
  }
  
  .circle-progress__content {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    width: 100%;
    height: 100%;
    border-radius: 50%;
  }
  
  @keyframes filling {
    from {
      stroke-dashoffset: var(--dash-array);
    }
    to {
      stroke-dashoffset: var(--dash-offset);
    }
  }
</style>